SET NAMES utf8mb4;
SET time_zone='+00:00';
CREATE TABLE IF NOT EXISTS business_entity_template_applications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_number VARCHAR(80) NOT NULL UNIQUE,template_code VARCHAR(80) NOT NULL,template_version VARCHAR(40) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'validated',manifest_json LONGTEXT NOT NULL,relationship_hash CHAR(64) NOT NULL,prepared_by BIGINT UNSIGNED NULL,reviewed_by BIGINT UNSIGNED NULL,approved_by BIGINT UNSIGNED NULL,evidence_note TEXT NOT NULL,applied_at DATETIME NULL,rolled_back_at DATETIME NULL,rollback_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS business_entities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,entity_code VARCHAR(80) NOT NULL UNIQUE,entity_name VARCHAR(190) NOT NULL,legal_name VARCHAR(240) NOT NULL,entity_type VARCHAR(48) NOT NULL,parent_entity_id BIGINT UNSIGNED NULL,company_id BIGINT UNSIGNED NULL UNIQUE,status VARCHAR(32) NOT NULL DEFAULT 'active',country_code CHAR(2) NOT NULL DEFAULT 'US',base_currency CHAR(3) NOT NULL DEFAULT 'USD',timezone VARCHAR(80) NOT NULL DEFAULT 'America/Phoenix',fiscal_calendar_code VARCHAR(80) NOT NULL DEFAULT 'CALENDAR',effective_from DATE NOT NULL,effective_to DATE NULL,application_id BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS business_entity_relationships(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NULL,from_entity_id BIGINT UNSIGNED NOT NULL,to_entity_id BIGINT UNSIGNED NOT NULL,relationship_type VARCHAR(48) NOT NULL,service_domain VARCHAR(80) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',effective_from DATE NOT NULL,effective_to DATE NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_business_entity_relationship(from_entity_id,to_entity_id,relationship_type,service_domain,effective_from));
CREATE TABLE IF NOT EXISTS business_entity_company_bindings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NULL,entity_id BIGINT UNSIGNED NOT NULL,company_id BIGINT UNSIGNED NOT NULL,binding_type VARCHAR(40) NOT NULL DEFAULT 'operational',is_primary TINYINT(1) NOT NULL DEFAULT 1,status VARCHAR(32) NOT NULL DEFAULT 'active',effective_from DATE NOT NULL,effective_to DATE NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_business_entity_company(entity_id,company_id,effective_from));
CREATE TABLE IF NOT EXISTS business_entity_module_profiles(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NULL,entity_id BIGINT UNSIGNED NOT NULL,module_code VARCHAR(80) NOT NULL,enabled TINYINT(1) NOT NULL DEFAULT 1,inheritance_mode VARCHAR(32) NOT NULL DEFAULT 'local',source_entity_id BIGINT UNSIGNED NULL,settings_json LONGTEXT NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_business_entity_module(entity_id,module_code));
CREATE TABLE IF NOT EXISTS business_entity_data_authorities(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NULL,entity_id BIGINT UNSIGNED NOT NULL,domain_code VARCHAR(80) NOT NULL,authority_entity_id BIGINT UNSIGNED NOT NULL,authority_mode VARCHAR(40) NOT NULL,override_policy VARCHAR(48) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',effective_from DATE NOT NULL,effective_to DATE NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_business_entity_authority(entity_id,domain_code,effective_from));
CREATE TABLE IF NOT EXISTS business_entity_access_scopes(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NULL,user_id BIGINT UNSIGNED NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,module_code VARCHAR(80) NOT NULL DEFAULT '*',scope_type VARCHAR(48) NOT NULL DEFAULT 'entity_only',include_descendants TINYINT(1) NOT NULL DEFAULT 0,status VARCHAR(32) NOT NULL DEFAULT 'active',effective_from DATE NOT NULL,effective_to DATE NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_business_entity_access(user_id,entity_id,module_code,effective_from));
CREATE TABLE IF NOT EXISTS business_entity_templates(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,template_code VARCHAR(80) NOT NULL,template_version VARCHAR(40) NOT NULL,template_name VARCHAR(190) NOT NULL,description TEXT NOT NULL,manifest_json LONGTEXT NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'active',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_business_entity_template(template_code,template_version));
CREATE TABLE IF NOT EXISTS integration_connections(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,connection_number VARCHAR(80) NOT NULL UNIQUE,connection_name VARCHAR(190) NOT NULL,provider VARCHAR(120) NOT NULL,system_type VARCHAR(48) NOT NULL,environment VARCHAR(32) NOT NULL,auth_type VARCHAR(48) NOT NULL,secret_reference VARCHAR(255) NOT NULL,adapter_version VARCHAR(40) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'draft',capabilities_json LONGTEXT NOT NULL,last_success_at DATETIME NULL,created_by BIGINT UNSIGNED NULL,reviewer_id BIGINT UNSIGNED NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS integration_entity_bindings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,connection_id BIGINT UNSIGNED NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,external_organization_id VARCHAR(190) NOT NULL,external_company_id VARCHAR(190) NOT NULL,external_tenant_id VARCHAR(190) NOT NULL,sync_direction VARCHAR(32) NOT NULL,enabled_domains_json LONGTEXT NOT NULL,data_authority VARCHAR(48) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'draft',effective_from DATE NOT NULL,effective_to DATE NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_integration_entity_binding(connection_id,entity_id,effective_from));
CREATE TABLE IF NOT EXISTS external_id_mappings(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,connection_id BIGINT UNSIGNED NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,domain_code VARCHAR(80) NOT NULL,internal_record_type VARCHAR(80) NOT NULL,internal_record_id BIGINT UNSIGNED NOT NULL,external_record_type VARCHAR(80) NOT NULL,external_record_id VARCHAR(255) NOT NULL,external_parent_id VARCHAR(255) NOT NULL,mapping_status VARCHAR(32) NOT NULL DEFAULT 'pending_review',effective_from DATE NOT NULL,effective_to DATE NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_external_id_mapping(connection_id,entity_id,domain_code,internal_record_type,internal_record_id,effective_from));
CREATE TABLE IF NOT EXISTS integration_sync_runs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,run_number VARCHAR(80) NOT NULL UNIQUE,connection_id BIGINT UNSIGNED NOT NULL,entity_id BIGINT UNSIGNED NULL,direction VARCHAR(32) NOT NULL,status VARCHAR(32) NOT NULL,records_read INT UNSIGNED NOT NULL DEFAULT 0,records_written INT UNSIGNED NOT NULL DEFAULT 0,records_failed INT UNSIGNED NOT NULL DEFAULT 0,started_at DATETIME NOT NULL,completed_at DATETIME NULL,checksum CHAR(64) NOT NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS integration_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,connection_id BIGINT UNSIGNED NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,direction VARCHAR(32) NOT NULL,event_type VARCHAR(80) NOT NULL,record_type VARCHAR(80) NOT NULL,record_id BIGINT UNSIGNED NOT NULL,idempotency_key CHAR(64) NOT NULL UNIQUE,payload_checksum CHAR(64) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'ready',attempt_count INT UNSIGNED NOT NULL DEFAULT 0,occurred_at DATETIME NOT NULL,processed_at DATETIME NULL,evidence_note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS integration_conflicts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,connection_id BIGINT UNSIGNED NOT NULL,entity_id BIGINT UNSIGNED NOT NULL,domain_code VARCHAR(80) NOT NULL,internal_record_type VARCHAR(80) NOT NULL,internal_record_id BIGINT UNSIGNED NOT NULL,external_record_id VARCHAR(255) NOT NULL,conflict_type VARCHAR(80) NOT NULL,status VARCHAR(32) NOT NULL DEFAULT 'open',internal_value_json LONGTEXT NOT NULL,external_value_json LONGTEXT NOT NULL,resolution_json LONGTEXT NULL,owner_id BIGINT UNSIGNED NULL,reviewer_id BIGINT UNSIGNED NULL,evidence_note TEXT NOT NULL,resolved_at DATETIME NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS business_entity_events(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,application_id BIGINT UNSIGNED NULL,entity_id BIGINT UNSIGNED NULL,event_type VARCHAR(80) NOT NULL,entity_type VARCHAR(80) NOT NULL,entity_record_id BIGINT UNSIGNED NOT NULL,from_status VARCHAR(32) NULL,to_status VARCHAR(32) NULL,severity VARCHAR(20) NOT NULL DEFAULT 'medium',evidence_note TEXT NOT NULL,created_by BIGINT UNSIGNED NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP);
INSERT IGNORE INTO permissions(permission_key,area,action,description) VALUES('entities.view','entities','view','View business entity hierarchy and integrations'),('entities.create','entities','create','Create business entities and templates'),('entities.edit','entities','edit','Edit entity relationships, authorities, scopes, and mappings'),('entities.apply','entities','apply','Apply reviewed entity templates'),('entities.review','entities','review','Review templates, mappings, and conflicts'),('entities.administer','entities','administer','Administer entity hierarchy and integration policy'),('entities.export','entities','export','Export business entity reports');
