SET @system_admin=(SELECT id FROM users WHERE status='active' ORDER BY id LIMIT 1);SET @reviewer=COALESCE((SELECT id FROM users WHERE status='active' AND id<>@system_admin ORDER BY id LIMIT 1),@system_admin);SET @approver=COALESCE((SELECT id FROM users WHERE status='active' AND id NOT IN(@system_admin,@reviewer) ORDER BY id LIMIT 1),@reviewer);
INSERT IGNORE INTO business_entity_template_applications(application_number,template_code,template_version,status,manifest_json,relationship_hash,prepared_by,reviewed_by,approved_by,evidence_note,applied_at,rollback_note) VALUES('ENT-APP-INITIAL-GRUBER','gruber_shared_services','1.0.0','applied','{"canonical_company_ids_preserved":true,"source":"existing_companies_and_relationships"}',SHA2('gruber-shared-services-company-ids',256),@system_admin,@reviewer,@approver,'Additive backfill of existing companies and relationships.',NOW(),'');
SET @application_id=(SELECT id FROM business_entity_template_applications WHERE application_number='ENT-APP-INITIAL-GRUBER');
INSERT IGNORE INTO business_entities(entity_code,entity_name,legal_name,entity_type,parent_entity_id,company_id,status,effective_from,application_id) VALUES('GRUBER-ENTERPRISE','Gruber Enterprise','Gruber Enterprise','enterprise_group',NULL,NULL,'active',CURRENT_DATE,@application_id);SET @root_id=(SELECT id FROM business_entities WHERE entity_code='GRUBER-ENTERPRISE');
INSERT IGNORE INTO business_entities(entity_code,entity_name,legal_name,entity_type,parent_entity_id,company_id,status,effective_from,application_id) VALUES('GRUBER-PROCUREMENT','Gruber Shared Procurement','Gruber Shared Procurement Services','shared_service',@root_id,NULL,'active',CURRENT_DATE,@application_id),('GRUBER-ACCOUNTS-PAYABLE','Gruber Shared Finance & Accounts Payable','Gruber Shared Finance Services','shared_service',@root_id,NULL,'active',CURRENT_DATE,@application_id);SET @procurement_id=(SELECT id FROM business_entities WHERE entity_code='GRUBER-PROCUREMENT');SET @finance_id=(SELECT id FROM business_entities WHERE entity_code='GRUBER-ACCOUNTS-PAYABLE');
INSERT IGNORE INTO business_entities(entity_code,entity_name,legal_name,entity_type,parent_entity_id,company_id,status,effective_from,application_id) SELECT CONCAT('COMP-',UPPER(code)),name,COALESCE(NULLIF(legal_name,''),name),'operating_company',@root_id,id,'active',CURRENT_DATE,@application_id FROM companies;
INSERT IGNORE INTO business_entity_company_bindings(application_id,entity_id,company_id,binding_type,is_primary,status,effective_from) SELECT @application_id,e.id,c.id,'operational',1,'active',CURRENT_DATE FROM companies c JOIN business_entities e ON e.company_id=c.id;
INSERT IGNORE INTO business_entity_relationships(application_id,from_entity_id,to_entity_id,relationship_type,service_domain,status,effective_from,evidence_note) SELECT @application_id,@root_id,e.id,'owns','governance','active',CURRENT_DATE,CONCAT('Canonical company ID ',e.company_id,' preserved.') FROM business_entities e WHERE e.company_id IS NOT NULL;
INSERT IGNORE INTO business_entity_relationships(application_id,from_entity_id,to_entity_id,relationship_type,service_domain,status,effective_from,evidence_note) SELECT @application_id,@procurement_id,e.id,'provides_service','procurement','active',CURRENT_DATE,'Shared procurement relationship.' FROM business_entities e WHERE e.company_id IS NOT NULL;
INSERT IGNORE INTO business_entity_relationships(application_id,from_entity_id,to_entity_id,relationship_type,service_domain,status,effective_from,evidence_note) SELECT @application_id,@finance_id,e.id,'provides_service','accounts_payable','active',CURRENT_DATE,'Shared finance relationship.' FROM business_entities e WHERE e.company_id IS NOT NULL;
INSERT IGNORE INTO business_entity_module_profiles(application_id,entity_id,module_code,enabled,inheritance_mode,source_entity_id,settings_json,status) SELECT @application_id,e.id,m.module_code,1,IF(m.module_code IN('accounts_payable','supplier_portal','strategy'),'inherited','local'),IF(m.module_code='accounts_payable',@finance_id,IF(m.module_code IN('supplier_portal','strategy'),@procurement_id,NULL)),'{}','active' FROM business_entities e JOIN(SELECT 'discovery' module_code UNION ALL SELECT 'suppliers' UNION ALL SELECT 'supplier_portal' UNION ALL SELECT 'accounts_payable' UNION ALL SELECT 'items' UNION ALL SELECT 'purchase_orders' UNION ALL SELECT 'inventory' UNION ALL SELECT 'savings' UNION ALL SELECT 'strategy' UNION ALL SELECT 'scorecards' UNION ALL SELECT 'imports')m WHERE e.company_id IS NOT NULL;
INSERT IGNORE INTO business_entity_data_authorities(application_id,entity_id,domain_code,authority_entity_id,authority_mode,override_policy,status,effective_from,evidence_note) SELECT @application_id,e.id,d.domain_code,CASE d.authority_role WHEN 'enterprise' THEN @root_id WHEN 'procurement' THEN @procurement_id WHEN 'finance' THEN @finance_id ELSE e.id END,d.authority_role,IF(d.authority_role='local','local_only','governed_override'),'active',CURRENT_DATE,'Initial Gruber authority policy.' FROM business_entities e JOIN(SELECT 'supplier_master' domain_code,'enterprise' authority_role UNION ALL SELECT 'item_master','enterprise' UNION ALL SELECT 'contracts','procurement' UNION ALL SELECT 'sourcing','procurement' UNION ALL SELECT 'purchase_orders','local' UNION ALL SELECT 'inventory','local' UNION ALL SELECT 'accounts_payable','finance' UNION ALL SELECT 'payments','finance' UNION ALL SELECT 'reporting','enterprise' UNION ALL SELECT 'security','enterprise')d WHERE e.company_id IS NOT NULL;
INSERT IGNORE INTO business_entity_access_scopes(application_id,user_id,entity_id,module_code,scope_type,include_descendants,status,effective_from) SELECT @application_id,cm.user_id,e.id,'*','entity_only',0,'active',CURRENT_DATE FROM company_memberships cm JOIN business_entities e ON e.company_id=cm.company_id WHERE cm.membership_status='active';
INSERT IGNORE INTO business_entity_access_scopes(application_id,user_id,entity_id,module_code,scope_type,include_descendants,status,effective_from) SELECT @application_id,ur.user_id,@root_id,'*','entity_and_descendants',1,'active',CURRENT_DATE FROM user_roles ur JOIN roles r ON r.id=ur.role_id WHERE r.code IN('system_administrator','executive');
INSERT IGNORE INTO business_entity_events(application_id,entity_id,event_type,entity_type,entity_record_id,from_status,to_status,severity,evidence_note,created_by) VALUES(@application_id,@root_id,'template_applied','business_entity_application',@application_id,'validated','applied','medium','Six companies and canonical relationships bound to the modular entity system.',@system_admin);
